<section class="trail-page"><header class="trail-hero card"><div><a class="back" href="<?=e(url('/dashboard'))?>">← Dashboard</a><span class="eyebrow">TRILHA PRINCIPAL</span><h1><?=e($course['title'])?></h1><p><?=e($course['description']??$course['short_description']??'')?></p></div><div class="score"><strong><?=number_format((float)$course['progress_pct'],0)?>%</strong><span>concluído</span><div class="progress"><span style="width:<?=(float)$course['progress_pct']?>%"></span></div></div></header><div class="section-head"><div><span class="eyebrow">MAPA DA CAMPANHA</span><h2>Módulos</h2></div><p>As bibliotecas complementares não precisam ser concluídas para avançar.</p></div><div class="timeline"><?php foreach($modules as $m):$locked=$m['user_status']==='locked';$done=$m['user_status']==='completed';?><article class="timeline-item <?=$locked?'locked':''?> <?=$done?'done':''?>"><div class="rail"><span><?=(int)$m['position']?></span></div><div class="card module-box"><div class="module-head"><div><span class="eyebrow">MÓDULO <?=(int)$m['position']?></span><h3><?=e($m['title'])?></h3></div><span class="badge <?=$locked?'locked':($done?'done':'active')?>"><?=$locked?'BLOQUEADO':($done?'CONCLUÍDO':'LIBERADO')?></span></div><p><?=e($m['description']??'')?></p><div class="meta"><span><?=(int)$m['required_phase_count']?> fases obrigatórias</span><?php if((int)$m['library_phase_count']):?><span><?=(int)$m['library_phase_count']?> biblioteca(s)</span><?php endif;?></div><div class="progress"><span style="width:<?=(float)$m['progress_pct']?>%"></span></div><?php if($locked):?><button class="secondary" disabled>🔒 Complete o módulo anterior</button><?php else:?><a class="primary" href="<?=e(url('/modulo/'.$m['id']))?>">Abrir módulo →</a><?php endif;?></div></article><?php endforeach;?></div></section>
